-- Sekolah Amanah Pixel: MySQL 5.7+ / MariaDB 10.2+
-- Import into the database selected in phpMyAdmin. Existing rows are preserved.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS amanah_posts (
  id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  post_date DATETIME NOT NULL,
  title TEXT NOT NULL,
  school VARCHAR(120) NOT NULL,
  category VARCHAR(32) NOT NULL,
  url TEXT NOT NULL,
  image TEXT NOT NULL,
  blocks JSON NOT NULL,
  INDEX amanah_posts_date (post_date, id),
  INDEX amanah_posts_school (school)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS amanah_settings (
  name VARCHAR(64) NOT NULL PRIMARY KEY,
  value JSON NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
COMMIT;
